74	void start_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments,
75	                             std::function<void(McpSetupResult)> done)
76	{
77	    if (arguments.empty()) {
78	        done({false, "Missing setup executable"});
79	        return;
80	    }
81	    struct Watch : wxEvtHandler {
82	        wxProcess process;
83	        wxTimer timer;
84	        std::function<void(McpSetupResult)> done;
85	        std::string output;
86	        std::chrono::steady_clock::time_point started;
87	        long pid{0};
88	        bool timed_out{false};
89	        bool finished{false};
90	        Watch(wxWindow*, std::function<void(McpSetupResult)> complete)
91	            : process(this), timer(this), done(std::move(complete)), started(std::chrono::steady_clock::now())
92	        {}
93	        void drain()
94	        {
95	            for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
96	                while (stream && stream->CanRead()) {
97	                    char buffer[4096];
98	                    stream->Read(buffer, sizeof buffer);
99	                    const auto size = stream->LastRead();
100	                    if (!size) break;
101	                    if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
102	                }
103	            }
104	        }
105	        void finish(McpSetupResult result)
106	        {
107	            if (finished) return;
108	            finished = true;
109	            timer.Stop();
110	            auto complete = std::move(done);
111	            complete(std::move(result));
112	            CallAfter([this] { delete this; });
113	        }
114	    };
115	    auto* watch = new Watch(parent, std::move(done));
116	    std::vector<wxString> values;
117	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
118	    std::vector<const wchar_t*> argv;
119	    for (const auto& value : values) argv.push_back(value.wc_str());
120	    argv.push_back(nullptr);
121	    watch->pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &watch->process);
122	    if (watch->pid <= 0) {
123	        watch->finish({false, "Could not start the client CLI. Use Copy or check its installation."});
124	        return;
125	    }
126	    watch->process.CloseOutput();
127	    watch->Bind(wxEVT_TIMER, [watch](wxTimerEvent&) {
128	        watch->drain();
129	        const auto elapsed = std::chrono::steady_clock::now() - watch->started;
130	        if (!watch->timed_out && elapsed > std::chrono::seconds(30)) {
131	            watch->timed_out = true;
132	            wxProcess::Kill(watch->pid, wxSIGTERM);
133	        } else if (watch->timed_out && elapsed > std::chrono::seconds(32))
134	            wxProcess::Kill(watch->pid, wxSIGKILL);
135	    });
136	    watch->Bind(wxEVT_END_PROCESS, [watch](wxProcessEvent& event) {
137	        if (event.GetPid() != watch->pid) { event.Skip(); return; }
138	        watch->drain();
139	        if (watch->timed_out)
140	            watch->finish({false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + watch->output});
141	        else
142	            watch->finish({event.GetExitCode() == 0,
143	                           "Client CLI exited with code " + std::to_string(event.GetExitCode()) + ".\n" + watch->output});
144	    });
145	    watch->timer.Start(30);
146	}
