16	bool executable_file(const fs::path& path)
17	{
18	    std::error_code error;
19	    const auto status = fs::status(path, error);
20	    if (error || !fs::is_regular_file(status)) return false;
21	#ifdef _WIN32
22	    return true;
23	#else
24	    return (status.permissions() & (fs::perms::owner_exec | fs::perms::group_exec | fs::perms::others_exec)) !=
25	           fs::perms::none;
26	#endif
27	}
