52	std::string command_on_path(const std::string& command)
53	{
54	#ifdef _WIN32
55	    const std::string filename = command + ".exe";
56	    const std::string path = env("PATH");
57	    const char separator = ';';
58	#else
59	    const std::string filename = command;
60	    const std::string path = env("PATH");
61	    const char separator = ':';
62	#endif
63	    std::string directory;
64	    std::istringstream stream(path);
65	    while (std::getline(stream, directory, separator)) {
66	        if (directory.empty()) continue;
67	        const auto candidate = fs::u8path(directory) / filename;
68	        if (executable_file(candidate)) return candidate.u8string();
69	    }
70	#ifndef _WIN32
71	    const auto home = env("HOME");
72	    for (const auto& extra : {fs::u8path(home) / ".local" / "bin", fs::path("/opt/homebrew/bin"), fs::path("/usr/local/bin")}) {
73	        const auto candidate = extra / filename;
74	        if (executable_file(candidate)) return candidate.u8string();
75	    }
76	#endif
77	    return {};
78	}
