names = []
canvas_path = proj / 'canvas.json'
canvas = json.loads(canvas_path.read_text())
# The first version of these boards was one set named first-run-NN; it is now variant A, so those names go.
removed = [k for k in canvas['boards'] if k.startswith('first-run-') and not k.startswith(('first-run-a-', 'first-run-b-'))]
for k in removed:
    del canvas['boards'][k]
    canvas['order'].remove(k)
    (proj / k).unlink(missing_ok=True)
for stem, title, inner, x, y in BOARDS:
    name = stem + '.dc.html'
    (proj / name).write_text(wrap(title.replace('First run ', ''), inner))
    names.append(name)
    canvas['boards'][name] = {'x': x, 'y': y, 'w': SCREEN_W, 'h': SCREEN_H, 'title': title, 'page': PAGE}
    if name not in canvas['order']:
        canvas['order'].append(name)
canvas['notes']['first-run-title'] = {'x': -1440, 'y': TOP_A - 100, 'text': 'First run · variant A: no welcome screen', 'kind': 'title1', 'size': 40, 'maxW': 2400, 'page': PAGE}
canvas['notes']['first-run-replaces'] = {'x': -1920, 'y': TOP_A, 'w': 420, 'page': PAGE, 'fill': 'purple',
    'text': 'For review, 2026-11-02. Kenneth is comparing two first-run flows: this one and variant B below. Either would replace the onboarding wizard, boards 00 to 11 and 17 to 18 on this page, and the Welcome screens 1b to 1d, which stay for comparison until he decides what to retire.\n\n'
            'Variant A: the person lands on Home, opens their own part, and hears about it before anyone asks for an account. The first message they send is what asks them to sign in, and what they typed stays in the box.\n\n'
            'The printer, in both variants: the one inside a 3MF (the “from the file” chip on the file-printer boards, page Printer & Material Settings), else OrcaSlicer’s printers imported from this computer, else a default the chip marks as assumed and the agent’s first words name. Never a silent default.\n\n'
            'Top row: someone who imported OrcaSlicer’s printers. Bottom row: no OrcaSlicer, so the assumed default (03b, drawn once for both variants), the example, and the two doors out. Plates are captured from the real app; the agent’s words are written for these boards, not model output.'}
canvas['notes']['first-run-b-title'] = {'x': -1440, 'y': TOP_B - 100, 'text': 'First run · variant B: one welcome screen', 'kind': 'title1', 'size': 40, 'maxW': 2400, 'page': PAGE}
canvas['notes']['first-run-b-about'] = {'x': -1920, 'y': TOP_B, 'w': 420, 'page': PAGE, 'fill': 'purple',
    'text': 'Variant B adds one welcome screen before the same Home, and nothing else of the wizard returns. It says what the program is in one line and offers three doors, each one step: your own API key, the first-month offer, or connecting Claude Code or Claude Desktop as an MCP server. A small “Just slice for now” sits under them. Every door lands on Home.\n\n'
            'After Home, variant A’s boards apply: 02a, 03a or 03b, 05 and 06, with the model picker already in the box. There is no sign-in gate, because the person already chose a door. Someone with an MCP connection or who chose Just slice gets no turn from the app, so their agent pane shows the doors again (06).\n\n'
            'Home has no agent pane in the app (the pane is collapsed on Home), so the state each door leaves is drawn at the top of the Printers column. The MCP command and settings are the real shape from Mcp/McpConnections.hpp, with a placeholder home folder.'}
for nid in ('first-run-title', 'first-run-replaces', 'first-run-b-title', 'first-run-b-about'):
    if nid not in canvas['noteOrder']:
        canvas['noteOrder'].append(nid)
canvas_path.write_text(json.dumps(canvas, ensure_ascii=False, indent=1))
print('\n'.join(names))
if removed:
    print('REMOVED ' + ' '.join(removed), file=sys.stderr)

