    line = lambda inner: f'<div style="{BOX}align-self:stretch;display:grid;grid-template-columns:{columns};gap:var(--space-8);padding:var(--space-4) 0;align-items:baseline;box-shadow:inset 0 -1px 0 0 var(--border-subtle)">{inner}</div>'
    out = [line(''.join(text('label', h, '--text-secondary', 'min-width:0' + (';text-align:right' if i == n - 1 else '')) for i, h in enumerate(head)))]
